class Wheel { String type; Wheel(String t) { type = t; } }
class Bicycle {
    private Wheel front, rear;
    Bicycle(String f, String r) {
        front = new Wheel(f);
        rear = new Wheel(r);
    }
    String describe() { return front.type + "+" + rear.type; }
}
System.out.println(new Bicycle("road", "road").describe());
